S = "Hakeem Force Academy"
QS = [
 (S, "What does the idiom 'out of temper' mean?", ["Angry or irritable", "Calm and relaxed", "Very happy", "Extremely tired"], 0,
  "To be out of temper means to be in a bad mood and easily angered.", "The opposite state is to be good-tempered, meaning calm and cheerful.", [2537]),
 (S, "What does the idiom 'to keep one's temper' mean?", ["To get angry quickly", "To remain calm and not lose control of anger", "To save money", "To keep a hot drink warm"], 1,
  "To keep one's temper means to stay calm even when provoked.", "The opposite idiom is 'to lose one's temper', meaning to become suddenly angry.", [2918]),
 (S, "What is one quarter of one tenth of 12?", ["0.3", "3", "0.03", "1.2"], 0,
  "One tenth of 12 is 1.2. One quarter of 1.2 is 1.2 / 4 = 0.3.", "A quarter of a number is the same as dividing it by 4.", [2648]),
 (S, "What is one third of 1/80?", ["1/160", "3/80", "1/240", "80/3"], 2,
  "One third of 1/80 = (1/3) x (1/80) = 1/240.", "Multiplying fractions means multiplying the numerators and the denominators.", [2712]),
 (S, "What is one third of 10?", ["30", "3", "10/3 (3 and 1/3)", "13"], 2,
  "One third of 10 = 10 / 3 = 3.33, which is 3 and 1/3.", "Ten is not exactly divisible by 3, so the answer is a fraction.", [2713]),
 (S, "Ali is 12 years old and he is three times as old as his sister. When Ali is 15 years old, how old will his sister be?", ["5 years", "6 years", "7 years", "9 years"], 2,
  "Sister's age now = 12 / 3 = 4 years. Ali will be 15 after 3 years, so the sister will be 4 + 3 = 7 years.", "The age gap between two people changes, but the number of years that pass is the same for both.", [658]),
 (S, "Ali is 6 years older than his sister. When Ali's age was three times his sister's age, how old was the sister?", ["2 years", "3 years", "6 years", "9 years"], 1,
  "Let the sister be x. Then Ali is x + 6 = 3x, so 2x = 6 and x = 3. Ali was then 9.", "The age difference between two people always stays the same.", [1392]),
 (S, "Ali is 5 years old and his sister is three times his age. How old will the sister be when Ali is 15 years old?", ["45 years", "20 years", "30 years", "25 years"], 3,
  "Sister's age now = 5 x 3 = 15. Ali needs 10 more years to reach 15, so the sister will be 15 + 10 = 25 years.", "The sister is always 10 years older than Ali in this problem.", [743]),
 (S, "Sara is three times as old as Ali. If Ali is 4 years old, how old will Sara be when Ali is 8 years old?", ["12 years", "24 years", "20 years", "16 years"], 3,
  "Sara's age now = 4 x 3 = 12. Ali becomes 8 after 4 years, so Sara will be 12 + 4 = 16 years.", "The ratio of ages changes with time, but the difference stays the same (8 years here).", [849]),
 (S, "In which country is the Three Gorges Dam located?", ["India", "China", "Brazil", "Russia"], 1,
  "The Three Gorges Dam is built on the Yangtze River in Hubei province, China.", "It is the largest hydroelectric power station in the world by installed capacity.", [2024]),
 (S, "Fill in the blank: Throw the pen ___ the dustbin.", ["at", "with", "into", "on"], 2,
  "The preposition 'into' shows movement towards the inside of something, so the pen goes into the dustbin.", "'In' shows position while 'into' shows movement toward the inside.", [373]),
 (S, "Khateeb ul Ambia (the orator among the prophets) is the title of which prophet?", ["Hazrat Shuaib (AS)", "Hazrat Musa (AS)", "Hazrat Ibrahim (AS)", "Hazrat Isa (AS)"], 0,
  "Hazrat Shuaib (AS) was known for his powerful and eloquent speech, so he is called Khateeb ul Ambia.", "Hazrat Musa (AS) is called Kalimullah, the one who spoke with Allah.", [2252]),
 (S, "Which number completes the pattern: 2x2 = 44, 2x3 = 49, 3x4 = 916, then 2x4 = ?", ["48", "816", "416", "168"], 2,
  "Each answer joins the squares of the two numbers: 2x2 gives 4 and 4, 2x3 gives 4 and 9, 3x4 gives 9 and 16. So 2x4 gives 4 and 16, which is 416.", "The first digits come from the square of the first number and the rest from the square of the second.", [1846]),
 (S, "In which province of Pakistan did the country carry out its nuclear tests in May 1998?", ["Punjab", "Sindh", "Khyber Pakhtunkhwa", "Balochistan"], 3,
  "The tests were carried out in the Chagai Hills in Chagai district, Balochistan.", "The Ras Koh Hills in the Chagai range was the site of the main tests of 28 May 1998.", [2087]),
 (S, "How many nuclear tests did Pakistan conduct in total in May 1998?", ["Six", "Five", "Seven", "Two"], 0,
  "Pakistan carried out five tests on 28 May 1998 and one more on 30 May 1998, which makes six in total.", "Pakistan celebrates 28 May as Youm-e-Takbeer.", [387]),
 (S, "Where is the Thal desert located in Pakistan?", ["Between the Indus and Jhelum rivers in Punjab", "In southeastern Sindh near India", "In the Chagai district of Balochistan", "In the Cholistan region near Bahawalpur"], 0,
  "The Thal desert lies in the Punjab province in the area between the Indus and Jhelum rivers, covering districts such as Bhakkar, Layyah, Khushab and Mianwali.", "The Thar desert is a different desert and lies in Sindh.", [1966, 567]),
 (S, "What is the normal term (tenure) of the National Assembly and a provincial assembly in Pakistan under the 1973 Constitution?", ["3 years", "5 years", "4 years", "6 years"], 1,
  "The Constitution of 1973 gives the National Assembly and the provincial assemblies a term of five years from their first meeting, unless dissolved earlier.", "The Senate is different: each Senator serves for six years.", [1037, 1069]),
]
